@IsTest private class MockedTransportSpec {
 private static Integer calls=0;
 private class MemoryMock implements HttpCalloutMock {
  public HttpResponse respond(HttpRequest request){
   MockedTransportSpec.calls++;
   HttpResponse response=new HttpResponse();response.setStatusCode(209);
   response.setBody(request==null?'null-request':request.getMethod()+':'+request.getBody());return response;
  }
 }
 private static String describe(HttpResponse response){return 'response:'+response.getStatusCode()+':'+response.getBody();}
 @IsTest static void observe(){
  Test.setMock(HttpCalloutMock.class,new MemoryMock());
  String valid;String blank;
  try{valid=describe(MockedTransportCaller.send());}catch(Exception e){valid='error:'+e.getTypeName()+':'+e.getMessage();}
  try{blank=describe(MockedTransportCaller.send(new HttpRequest()));}catch(Exception e){blank='error:'+e.getTypeName()+':'+e.getMessage();}
  System.assert(false,'P|MT01T|valid:'+valid+'|blank:'+blank+'|calls:'+calls);
 }
}

